    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    fg = next(v for v, n in counts.most_common() if v != bg)
    pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == fg]
    out = [row[:] for row in grid]
    if not pts:
        return out
    r0, r1 = min(r for r, c in pts), max(r for r, c in pts)
    c0, c1 = min(c for r, c in pts), max(c for r, c in pts)
    # Complete the outer rectangular border of the foreground pattern.
    for c in range(c0, c1 + 1):
        if grid[r0][c] == bg:
            out[r0][c] = 2
        if grid[r1][c] == bg:
            out[r1][c] = 2
    for r in range(r0, r1 + 1):
        if grid[r][c0] == bg:
            out[r][c0] = 2
        if grid[r][c1] == bg:
            out[r][c1] = 2
    # Fill horizontal gaps on interior rows having at least three foreground
    # cells; two endpoint cells alone are the sides of a hollow frame.
    for r in range(r0 + 1, r1):
        cs = [c for c in range(c0, c1 + 1) if grid[r][c] == fg]
        if len(cs) >= 3:
            for c in range(min(cs), max(cs) + 1):
                if grid[r][c] == bg:
                    out[r][c] = 2
    return out
