    from collections import Counter
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    fg = next(v for v, _ in counts.most_common() if v != bg)
    pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == fg]
    out = [row[:] for row in grid]
    if not pts:
        return out
    r0 = min(r for r, c in pts)
    r1 = max(r for r, c in pts)

    # Fill horizontal spans on the top/bottom edge, or where at least three
    # same-color marks indicate a horizontal stroke.
    for r in range(h):
        cols = [c for c in range(w) if grid[r][c] == fg]
        if r in (r0, r1) or len(cols) >= 3:
            if cols:
                for c in range(min(cols), max(cols) + 1):
                    if grid[r][c] == bg:
                        out[r][c] = 2

    # Join repeated marks in each column; missing cells between their extremes
    # are gaps in the vertical stroke.
    for c in range(w):
        rows = [r for r in range(h) if grid[r][c] == fg]
        if len(rows) >= 2:
            for r in range(min(rows), max(rows) + 1):
                if grid[r][c] == bg:
                    out[r][c] = 2
